import {wattsSource,freshWattsWork,validWattsSource,validWattsWork,changeWattsWork,powerNotesView,keepPowerSheet,lastPowerSheet} from './watts-desk-core.mjs';
import {hearButton} from './play-media.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>structuredClone(x);
const button=(action,label,disabled=false,extra='')=>`<button type="button" data-watts-action="${action}"${disabled?' disabled':''} ${extra}>${label}</button>`;
let visit=null,generation=0;
export function resetWattsVisit(){visit=null;generation++;}
function session(book,owner){
 if(!visit||visit.book!==book||visit.owner!==owner){const source=wattsSource();visit={book,owner,source,work:freshWattsWork(source),page:'draft',keptId:null,notice:'',folds:{}};}
 return visit;
}
function current(s,book){
 if(s.page==='shelf')return null;
 if(s.page==='kept'){const item=powerNotesView(book).items.find(i=>i.id===s.keptId&&i.readable);return item?{source:item.raw.source,work:item.raw.work,mutable:false,item}:null;}
 return validWattsSource(s.source)&&validWattsWork(s.source,s.work)?{source:s.source,work:s.work,mutable:true}:null;
}
function strip(source,machine,seconds){
 const joules=machine.watts*seconds,count=seconds/source.stepSeconds;
 return `<div class="watts-strip" data-joules="${joules}" data-axis-max="${source.axisMax}" role="img" aria-label="${joules} joules on a shared zero to ${source.axisMax} joule scale"><div class="watts-fill" style="width:${100*joules/source.axisMax}%">${Array.from({length:count},()=>'<span></span>').join('')}</div></div><div class="watts-axis" aria-hidden="true"><span>0 J</span><span>${source.axisMax} J</span></div>`;
}
function cards(c){const {source:s,work:w,mutable}=c,list=w.mode==='job'?w.jobDurations:w.durations;
 return `<div class="watts-machines">${s.machines.map((m,i)=>{const seconds=list.find(d=>d.machineId===m.id).seconds,joules=m.watts*seconds,max=w.mode==='job'?w.target/m.watts:s.maxSeconds;
 return `<section class="watts-machine" data-watts-card="${esc(m.id)}"><div class="watts-machine-heading"><svg class="watts-winch" viewBox="0 0 100 75" aria-hidden="true"><path d="M10 65H90M20 65V15H73V65M20 15L73 65M73 15L20 65"/><circle cx="47" cy="24" r="12"/><path d="M47 12V36M35 24H59M59 24H84V43"/><rect x="77" y="43" width="14" height="18"/></svg><div><h3>${esc(m.label)}</h3><p><strong>${m.watts} watts</strong> · ${m.watts} joules each second</p></div></div><p class="watts-amount"><strong data-watts-joules>${joules}</strong> joules</p>${strip(s,m,seconds)}<p class="watts-duration"><strong data-watts-seconds>${seconds}</strong> model seconds</p>${mutable?`<div class="watts-time-controls">${button('time',`Remove ${s.stepSeconds} seconds`,seconds===0,`data-watts-machine="${esc(m.id)}" data-watts-delta="-${s.stepSeconds}" aria-label="${esc(m.label)}: Remove ${s.stepSeconds} seconds"`)}${button('time',`Add ${s.stepSeconds} seconds`,seconds>=max,`data-watts-machine="${esc(m.id)}" data-watts-delta="${s.stepSeconds}" aria-label="${esc(m.label)}: Add ${s.stepSeconds} seconds"`)}</div>`:''}</section>`;}).join('')}</div>`;
}
function worked(c){if(!c.work.workedShown)return '';const list=c.work.mode==='job'?c.work.jobDurations:c.work.durations;return `<section class="watts-help" data-watts-worked><h3>Show how · energy = power × time</h3>${c.source.machines.map(m=>{const t=list.find(d=>d.machineId===m.id).seconds,e=m.watts*t;return `<p><strong>${esc(m.label)}</strong>: ${m.watts} watts × ${t} seconds = ${e} joules.${t>0?`<br>${e} joules ÷ ${t} seconds = ${m.watts} watts.`:` No energy has transferred yet. We cannot find a rate by dividing zero energy by zero seconds; the model sets this machine’s rate.`}</p>`;}).join('')}</section>`;}
function finished(c){if(c.work.mode!=='job'||!c.work.finishedShown)return '';const powers=c.source.machines.map(m=>m.watts),unequal=new Set(powers).size>1;return `<section class="watts-help" data-watts-finished><h3>Finished comparison from the model · ${c.work.target} joules</h3><ul>${c.source.machines.map(m=>`<li>${esc(m.label)}: ${m.watts} watts × ${c.work.target/m.watts} seconds = ${c.work.target} joules.</li>`).join('')}</ul><p>Same target: compare the finishing times. With constant delivered power and no losses, ${unequal?'higher power finishes this same energy job sooner. It does not need more delivered energy for this job.':'equal powers take equal times for this job.'} ${unequal?'When power rates differ, different running times can reverse which machine transfers more altogether.':''}</p><p>This comparison is shown as help. Your own model seconds above stay as you set them.</p></section>`;}
function shelf(book){const v=powerNotesView(book);return `<section class="watts-shelf"><h2 id="watts-question" tabindex="-1">Kept sheets</h2><p>Copies of the model and your settings. A kept sheet stays unchanged. It does not say whether you solved a problem by yourself.</p>${v.status==='unavailable'?'<p>Earlier sheets are retained in Grown-up notes. This format cannot accept another sheet here.</p>':''}${v.items.length?`<ol>${v.items.map(i=>`<li value="${i.index+1}">${i.readable?`<strong>Sheet ${i.index+1} · ${esc(i.raw.source.title)}</strong><div class="watts-actions">${button('open','Open sheet',false,`data-watts-id="${esc(i.id)}" aria-label="Open Sheet ${i.index+1}"`)}${button('again','Try this sheet again',false,`data-watts-id="${esc(i.id)}" aria-label="Try Sheet ${i.index+1} again"`)}</div>`:'Earlier sheet unavailable here. Its original stays unchanged in Grown-up notes.'}</li>`).join('')}</ol>`:'<p>No sheets kept yet. An unfinished model can be kept too.</p>'}${button('draft','Return to this visit’s draft')}</section>`;}
function model(c,folds){const {source:s,work:w,mutable}=c;return `<section data-watts-turn>${c.item?`<p class="watts-source">Sheet ${c.item.index+1} · ${esc(s.title)} · kept copy</p>`:''}<p class="watts-small">Invented winches. Constant delivered power; losses ignored.</p><nav class="watts-actions" aria-label="Watts Desk turns">${['durations','job'].map(mode=>button('mode',mode==='durations'?'Choose durations':'Same energy job',!mutable,`data-watts-mode="${mode}" aria-pressed="${w.mode===mode}"`)).join('')}</nav><h2 id="watts-question" tabindex="-1">${w.mode==='durations'?'Do faster transfers always mean more energy?':`Every winch must deliver ${w.target} joules`}</h2><p>${w.mode==='durations'?'Try equal times, then different durations. Compare rates and total energy.':'Which needs fewer model seconds? Add model seconds to each winch, or open the finished comparison. Reaching the target is a picture of the model job, not a test result.'}</p>${w.mode==='job'?`<div class="watts-actions" role="group" aria-label="Energy target">${s.targets.map(t=>button('target',`${t} joules`,!mutable,`data-watts-target="${t}" aria-pressed="${w.target===t}"`)).join('')}</div>`:''}${cards(c)}<p class="watts-small">${esc(s.origin)}</p><p class="watts-small">One watt means one joule each second. ${esc(s.limit)} Removing seconds revises the imagined run.</p><div class="watts-actions">${mutable?button('worked',w.workedShown?'Hide Show how':'Show how',false,`aria-pressed="${w.workedShown}"`):''}${mutable&&w.mode==='job'?button('finished','Show the finished comparison',w.finishedShown):''}${mutable?button('example',w.exampleSeen===0?'An example in parts':w.exampleSeen<s.teaching.length?'Next example part':'Example complete',w.exampleSeen===s.teaching.length):''}</div>${worked(c)}${finished(c)}${w.exampleSeen?`<section class="watts-help" data-watts-example><h3>An example in parts · shown as help</h3><ol>${s.teaching.slice(0,w.exampleSeen).map(t=>`<li>${esc(t)}</li>`).join('')}</ol></section>`:''}<details data-watts-fold="words" ${folds.words?'open':''}><summary>Model and word help</summary><dl>${s.glossary.map(g=>`<dt>${esc(g.term)}</dt><dd>${esc(g.meaning)}</dd>`).join('')}</dl></details><div class="watts-actions watts-keep">${mutable?button('keep','Keep this sheet'):button('again','Try this sheet again',false,`data-watts-id="${esc(c.item.id)}"`)}${hearButton('','Hear this turn').replace('<button','<button data-watts-hear')}</div><p class="watts-small">${mutable?'Leaving without Keep loses this visit’s draft. You can keep an unfinished sheet, including zeros.':'This copy stays as it was. Try this sheet again makes a new draft; the earlier sheet stays unchanged.'}</p></section>`;}
export function wattsDeskPage(book,owner){const s=session(book,owner),c=current(s,book);return `<div class="watts-page" data-watts-root${s.page==='kept'?' data-watts-kept':''}><header class="watts-header"><div class="watts-actions">${button('back','Back to the Energy Book')}${button('shelf','Kept sheets',false,`aria-pressed="${s.page==='shelf'}"`)}</div><h1>Watts Desk</h1><p>Compare model winches for the town’s upper storeroom.</p></header>${s.page==='shelf'?shelf(book):c?model(c,s.folds):'<h2 id="watts-question" tabindex="-1">This sheet is unavailable here</h2><p>Its original remains in Grown-up notes.</p>'}<p id="watts-status" role="status" tabindex="-1" class="${s.notice?'watts-notice':'sr-only'}">${esc(s.notice)}</p><footer><a href="#notes">Grown-up notes</a><details data-watts-fold="grownups" ${s.folds.grownups?'open':''}><summary>For grown-ups</summary><p>This is a constant delivered-power model, not appliance input power, real motor performance, efficiency or energy created from nothing. Supplied numerical results and manual examples are support, never independent assessment. The earlier Mill’s chips have no joule value or time scale. The Lift Yard does not measure time. These surfaces cannot be combined to calculate a real power rating.</p><p>For the same energy job in this ideal model, twice the delivered power means half the time; equal power increases do not mean equal time decreases.</p><p>A pull limit in newtons is not a power rating in watts. Elapsed time and transferred energy determine average power; a steady rate is a separate assumption.</p></details></footer></div>`;}
export function bindWattsDesk(book,ctx){
 const root=document.querySelector('[data-watts-root]');if(!root)return;const owner=ctx.explorerId(),s=session(book,owner),binding=++generation,captured=current(s,book);
 const live=node=>root.isConnected&&node?.isConnected&&generation===binding&&visit===s&&ctx.notebook()===book&&ctx.explorerId()===owner&&ctx.isActive?.()!==false&&location.hash==='#mill/energy'&&(['back','shelf','draft'].includes(node.dataset.wattsAction)||(s.page==='shelf'||!!current(s,book))&&(!captured||current(s,book)?.source===captured.source));
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();};
 const redraw=(focus='#watts-question')=>{stop();ctx.render();const node=document.querySelector(focus),target=node&&!node.disabled?node:node?.closest('.watts-actions')?.querySelector('button:not(:disabled)')||document.querySelector('#watts-question');target?.focus({preventScroll:true});};
 root.querySelectorAll('[data-watts-action]').forEach(node=>node.addEventListener('click',()=>{if(!live(node)||node.disabled)return;const action=node.dataset.wattsAction,c=current(s,book);stop();s.notice='';
 if(action==='back'){ctx.onBack?.();return;}
 if(action==='shelf'){s.page='shelf';redraw();return;}
 if(action==='draft'){s.page='draft';redraw();return;}
 if(action==='open'||action==='again'){const item=powerNotesView(book).items.find(i=>i.id===node.dataset.wattsId&&i.readable);if(!item)return;if(action==='open'){s.keptId=item.id;s.page='kept';}else{s.source=clone(item.raw.source);s.work=clone(item.raw.work);s.page='draft';}redraw();return;}
 if(!c?.mutable)return;
 if(action==='keep'){const id=keepPowerSheet(book,c.source,c.work,{canExport:ctx.canExport});if(!id){s.notice='This draft has not been kept. Your earlier kept sheets remain in Grown-up notes. This draft lasts only while you stay at this table; compare or explain it together before leaving.';redraw('#watts-status');return;}s.keptId=id;s.page='kept';const saved=ctx.save?.();s.notice=saved?.enabled===false?'This sheet is kept in this open page, but saving is off. Download Grown-up notes before closing if you want to bring it back.':saved?.ok===false?'This sheet is kept in this open page, but device storage did not save. Download Grown-up notes before closing if you want to bring it back.':'Sheet kept. The model and these settings stay together.';redraw('#watts-status');return;}
 let key=action,value;if(action==='mode')value=node.dataset.wattsMode;else if(action==='target')value=Number(node.dataset.wattsTarget);else if(action==='time')value={id:node.dataset.wattsMachine,delta:Number(node.dataset.wattsDelta)};else if(!['worked','example','finished'].includes(action))return;
 const next=changeWattsWork(c.source,c.work,key,value);if(!validWattsWork(c.source,next))return;s.work=next;
 if(action==='time'){const m=c.source.machines.find(m=>m.id===value.id),list=next.mode==='job'?next.jobDurations:next.durations,t=list.find(d=>d.machineId===value.id).seconds;s.notice=`${m.label}: ${t} seconds, ${m.watts*t} joules.`;const max=next.mode==='job'?next.target/m.watts:c.source.maxSeconds,delta=t===0?c.source.stepSeconds:t===max?-c.source.stepSeconds:value.delta;redraw(`[data-watts-machine="${CSS.escape(value.id)}"][data-watts-delta="${delta}"]`);}else redraw(['worked','example','finished'].includes(action)?`[data-watts-action="${action}"]`:'#watts-question');
 }));
 root.querySelectorAll('[data-watts-fold]').forEach(node=>node.addEventListener('toggle',()=>{if(live(node)){s.folds[node.dataset.wattsFold]=node.open;stop();}}));
 root.addEventListener('click',event=>{const node=event.target.closest?.('[data-watts-hear]');if(!node)return;if(!live(node)){event.preventDefault();event.stopImmediatePropagation();return;}const c=current(s,book);if(!c)return;stop();const turn=root.querySelector('[data-watts-turn]');if(!turn)return;const hidden=[...turn.querySelectorAll('button,[aria-hidden=true]')].map(n=>[n,n.style.getPropertyValue('display'),n.style.getPropertyPriority('display')]);
 // Read the visible DOM once, excluding controls/decoration without exposing closed help.
 try{for(const[n]of hidden)n.style.setProperty('display','none','important');node.dataset.speak=turn.innerText.replace(/\bW\b/g,'watts').replace(/\bJ\b/g,'joules').replaceAll('×',' times ').replaceAll('÷',' divided by ');}finally{for(const[n,value,priority]of hidden){if(value)n.style.setProperty('display',value,priority);else n.style.removeProperty('display');}}},true);
}
export function wattsLiftInvitation(book){const item=lastPowerSheet(book);if(!item)return '';return `<aside class="watts-lift-invitation"><h3>Bring a Watts sheet</h3><p><strong>Sheet ${item.index+1} · ${esc(item.raw.source.title)}</strong></p><p><a href="#mill/energy">Open the Mill, then Watts Desk → Kept sheets</a>.</p><p>Both count energy in joules. This ramp’s rope work is the energy transferred to the load. In the Watts sheet, power × time gave joules. What else would you need to work out the ramp’s average power? This yard has no elapsed-time measurement, so it cannot give a power answer.</p><details><summary>For grown-ups</summary><p>Elapsed time and transferred energy determine average power; a steady rate is a separate assumption. State which work or energy transfer is being timed. A pull limit in newtons is not a power rating in watts.</p></details></aside>`;}
